<script setup lang="ts">
import {ref,watch} from 'vue';import {request} from './service';
const input=ref('{"posts":[{"title":"一篇新草稿","slug":"new-draft","category":"日常手记","content":"## 正文\\n\\n记录一些想法。"}]}'),report=ref<any>(null),busy=ref(false),notice=ref(''),done=ref(false);
watch(input,()=>{report.value=null;notice.value='';done.value=false;});
async function file(event){const f=event.target.files?.[0];if(!f)return;if(f.size>2*1024*1024){notice.value='JSON 文件不能超过 2MB';return;}input.value=await f.text();}
async function validate(){busy.value=true;notice.value='';try{const body=JSON.parse(input.value);report.value=await request('/api/private/imports/validate','POST',body);}catch(e){notice.value=e instanceof SyntaxError?'JSON 格式错误，请检查引号、逗号与括号。':e.message;}finally{busy.value=false;}}
async function submit(){if(!confirm('将这些文章作为私有草稿导入？'))return;busy.value=true;try{const result=await request('/api/private/imports','POST',JSON.parse(input.value));notice.value=`已创建 ${result.created.length} 篇草稿，可以到创作区继续编辑。`;done.value=true;report.value=null;}catch(e){notice.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="import-page"><span class="space-eyebrow">CONTENT IMPORT / DRAFT FIRST</span><h1>把整理好的文字带进来。</h1><p>每批最多 50 篇文章，先校验，再整体创建草稿。不会覆盖旧文章，也不会自动公开。</p><input type="file" accept="application/json,.json" aria-label="选择 JSON 文件" @change="file"/><el-input v-model="input" type="textarea" :autosize="{minRows:16,maxRows:30}" aria-label="文章 JSON"/><div class="import-actions"><el-button :loading="busy" :disabled="done" @click="validate">校验 JSON</el-button><el-button v-if="report?.valid" type="primary" :loading="busy" @click="submit">确认导入 {{report.count}} 篇草稿</el-button><RouterLink to="/article/articleList">查看草稿 ↗</RouterLink></div><p v-if="report" role="status">{{report.valid?'格式校验通过，共 '+report.count+' 篇。':'有字段或重复内容需要修正。'}}</p><ul><li v-for="error in report?.errors||[]" :key="error.index">第 {{error.index+1}} 篇：{{error.message}}</li></ul><p v-if="notice" role="status">{{notice}}</p></section></template>
<style scoped>.import-page{max-width:1000px;margin:auto}.import-page h1{font-size:28px;margin:14px 0}.import-page p,.import-page li{font-size:13px;line-height:1.8;color:var(--studio-muted)}.import-page>input{display:block;margin:25px 0 18px;font-size:13px;max-width:100%}.import-page :deep(textarea){font:13px/1.8 ui-monospace,Consolas,monospace}.import-actions{display:flex;gap:15px;align-items:center;flex-wrap:wrap;margin:20px 0}.import-actions a{font-size:12px}@media(max-width:650px){.import-page h1{font-size:24px}}</style>
